/**
 * Document storage for a property case. The case id is a long random id generated by the
 * app (an unguessable capability); there are no user accounts yet. Files are kept on the
 * server's data volume in Israel, one folder per case.
 */
import type { Database } from "bun:sqlite";
import { mkdirSync } from "node:fs";

export const MAX_BYTES = 25 * 1024 * 1024;
const ALLOWED = /^(application\/pdf|image\/(jpeg|png|heic|webp)|application\/(msword|vnd\.openxmlformats-officedocument\.wordprocessingml\.document)|application\/octet-stream)$/;

export async function storeDocument(db: Database, caseId: string, req: Request): Promise<[unknown, number]> {
  const form = await req.formData();
  const file = form.get("file");
  const kind = String(form.get("kind") ?? "other").replace(/[^a-z0-9_]/g, "").slice(0, 30) || "other";
  if (!(file instanceof File)) return [{ error: "file required" }, 400];
  if (file.size > MAX_BYTES) return [{ error: "file too large (25 MB max)" }, 413];
  if (file.type && !ALLOWED.test(file.type)) return [{ error: `file type not accepted: ${file.type}` }, 415];
  const id = crypto.randomUUID();
  const safe = file.name.replace(/[^\p{L}\p{N}._-]+/gu, "_").slice(-120);
  const dir = `${process.env.DATA_DIR ?? "data"}/docs/${caseId}`;
  mkdirSync(dir, { recursive: true });
  const path = `${dir}/${id}-${safe}`;
  await Bun.write(path, file);
  db.query(`INSERT INTO documents (id, case_id, kind, file_name, mime, size, path, added_at) VALUES (?, ?, ?, ?, ?, ?, ?, ?)`).run(
    id, caseId, kind, file.name, file.type, file.size, path, new Date().toISOString(),
  );
  return [{ id }, 200];
}

export function listDocuments(db: Database, caseId: string) {
  return db.query(`SELECT id, kind, file_name AS fileName, mime, size, added_at AS addedAt FROM documents WHERE case_id = ? ORDER BY added_at`).all(caseId);
}
